'use strict';

const assert = require('node:assert');
const common = require('../lib/common');

describe('lib/common queueSend', function () {
    function makeNode() {
        return {
            ratelimit: 0,
            statusCalls: [],
            sent: [],
            eventHandler: {
                publishCommand(thing, item, payload) {
                    this._sent = this._sent || [];
                }
            },
            status(s) { this.statusCalls.push(s); }
        };
    }

    it('drains the whole queue and publishes each command in order', function () {
        const published = [];
        const node = makeNode();
        node.eventHandler.publishCommand = (thing, item, payload) =>
            published.push({ thing, item, payload });

        const queue = [
            { thing: 't1', item: 'i1', payload: 'a' },
            { thing: 't2', item: 'i2', payload: 'b' },
            { thing: 't3', item: 'i3', payload: 'c' }
        ];

        common.queueSend(node, queue, 0);

        assert.deepStrictEqual(published.map(p => p.payload), ['a', 'b', 'c']);
        assert.strictEqual(queue.length, 0);
    });

    it('calls onFinish once the queue empties', function () {
        let finished = 0;
        const node = makeNode();
        node.eventHandler.publishCommand = () => {};
        common.queueSend(node, [{ thing: 't', item: 'i', payload: 1 }], 0, () => { finished += 1; });
        assert.strictEqual(finished, 1);
    });

    it('does not throw when onFinish is omitted (group-style call)', function () {
        const node = { ratelimit: 0, eventHandler: { publishCommand() {} }, status() {} };
        assert.doesNotThrow(() => common.queueSend(node, [{ thing: 't', item: 'i', payload: 1 }]));
    });

    it('treats a null/undefined qLast as "send now"', function () {
        const published = [];
        const node = makeNode();
        node.eventHandler.publishCommand = (t, i, p) => published.push(p);
        common.queueSend(node, [{ thing: 't', item: 'i', payload: 'x' }], null);
        assert.deepStrictEqual(published, ['x']);
    });
});

'use strict';

const assert = require('node:assert');
const {
    MCP_TOOLS, MCP_TOOLS_ADMIN, MCP_ADMIN_TOOL_NAMES, expandHaTypeFilter
} = require('../core/mcp-tools');

describe('core/mcp-tools catalog', function () {
    it('every tool has a name, description and object inputSchema', function () {
        for (const t of [...MCP_TOOLS, ...MCP_TOOLS_ADMIN]) {
            assert.ok(t.name && typeof t.name === 'string', 'missing name');
            assert.ok(t.description && typeof t.description === 'string', t.name + ' missing description');
            assert.ok(t.inputSchema && t.inputSchema.type === 'object', t.name + ' bad inputSchema');
        }
    });

    it('has no duplicate tool names', function () {
        const names = [...MCP_TOOLS, ...MCP_TOOLS_ADMIN].map(t => t.name);
        assert.strictEqual(names.length, new Set(names).size, 'duplicate tool name');
    });

    it('admin tool names set matches the admin tool list', function () {
        assert.strictEqual(MCP_ADMIN_TOOL_NAMES.size, MCP_TOOLS_ADMIN.length);
        for (const t of MCP_TOOLS_ADMIN) {
            assert.ok(MCP_ADMIN_TOOL_NAMES.has(t.name), t.name + ' not in admin set');
        }
    });

    it('admin tools are not also listed as regular tools', function () {
        const regular = new Set(MCP_TOOLS.map(t => t.name));
        for (const t of MCP_TOOLS_ADMIN) {
            assert.ok(!regular.has(t.name), t.name + ' is both admin and regular');
        }
    });

    it('expandHaTypeFilter returns an array', function () {
        assert.ok(Array.isArray(expandHaTypeFilter('light')));
    });
});

